"""
Key management: generation, derivation, persistence.

Design notes
------------
* The master key is generated by :func:`Crypto.Random.get_random_bytes`
  (a CSPRNG). 128 bits is sufficient for AES-128.
* Sub-keys for each address type are derived with **HKDF-SHA256**
  (RFC 5869) instead of raw SHA-256 truncation. HKDF gives us proper
  key-separation guarantees: even if one sub-key is somehow leaked, the
  others remain pseudo-random. Truncating SHA-256 (as the original code
  did) works in practice but isn't the documented primitive for this.
* On POSIX systems the key file is created with mode ``0o600`` so it's
  readable only by the owner — the previous code dropped a base64 key
  next to the capture with default umask permissions.
* The key file is written atomically via a same-directory temp file +
  ``os.replace`` so a crash mid-write can never produce a corrupt file.
* An optional **HMAC integrity tag** is written next to the key. When
  loading the key, the tag is verified, so accidental edits to the file
  are caught before they cause garbled decryption output.
"""

from __future__ import annotations

import base64
import hmac
import logging
import os
import stat
import sys
import tempfile
import time
from dataclasses import dataclass
from typing import Optional

from Crypto.Protocol.KDF import HKDF  # type: ignore
from Crypto.Hash import SHA256  # type: ignore
from Crypto.Random import get_random_bytes  # type: ignore

from ..core.exceptions import InvalidKeyError, KeyDerivationError

logger = logging.getLogger(__name__)

KEY_LENGTH = 16  # AES-128
_HKDF_SALT = b"anonymizer.v1.salt"
_HMAC_TAG_LABEL = b"anonymizer.v1.tag"

# HKDF "info" labels — domain-separate the sub-keys.
_INFO_IPV4 = b"anonymizer.v1.subkey.ipv4"
_INFO_IPV6 = b"anonymizer.v1.subkey.ipv6"
_INFO_MAC = b"anonymizer.v1.subkey.mac"
_INFO_PORT = b"anonymizer.v1.subkey.port"


@dataclass(frozen=True)
class SubKeys:
    """Container for the four derived sub-keys (16 bytes each)."""

    ipv4: bytes
    ipv6: bytes
    mac: bytes
    port: bytes


def derive_subkeys(master_key: bytes) -> SubKeys:
    """Derive four 16-byte sub-keys from a 16-byte master key via HKDF.

    Raises :class:`KeyDerivationError` on any failure (e.g. wrong length).
    """
    if len(master_key) != KEY_LENGTH:
        raise KeyDerivationError(
            f"Master key must be {KEY_LENGTH} bytes; got {len(master_key)}"
        )
    try:
        ipv4 = HKDF(master_key, KEY_LENGTH, _HKDF_SALT, SHA256, context=_INFO_IPV4)
        ipv6 = HKDF(master_key, KEY_LENGTH, _HKDF_SALT, SHA256, context=_INFO_IPV6)
        mac = HKDF(master_key, KEY_LENGTH, _HKDF_SALT, SHA256, context=_INFO_MAC)
        port = HKDF(master_key, KEY_LENGTH, _HKDF_SALT, SHA256, context=_INFO_PORT)
    except Exception as exc:  # noqa: BLE001 - PyCryptodome wraps several
        raise KeyDerivationError(f"HKDF failed: {exc}") from exc
    return SubKeys(ipv4=ipv4, ipv6=ipv6, mac=mac, port=port)


def generate_master_key() -> bytes:
    """Return a fresh 16-byte master key from the system CSPRNG."""
    return get_random_bytes(KEY_LENGTH)


def _integrity_tag(key: bytes) -> str:
    """Return a short, deterministic HMAC tag for the key, in hex.

    The tag is *not* a MAC of the file's plaintext — it's a fingerprint
    that lets us detect tampering or accidental edits of the key file.
    """
    return hmac.new(_HMAC_TAG_LABEL, key, "sha256").hexdigest()[:16]


def save_key(key: bytes, path: str, *, source_filename: str = "") -> None:
    """Persist ``key`` to ``path`` atomically with mode 0600.

    The file is human-readable: first line is the base64 key, followed by
    a metadata block (comments + tag). The metadata is informational; the
    key itself is what's loaded.
    """
    if len(key) != KEY_LENGTH:
        raise InvalidKeyError(f"key must be {KEY_LENGTH} bytes; got {len(key)}")

    key_b64 = base64.b64encode(key).decode("ascii")
    tag = _integrity_tag(key)
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")

    contents = (
        f"{key_b64}\n"
        f"# Anonymizer AES-128 key (base64).\n"
        f"# Source file : {source_filename}\n"
        f"# Generated   : {timestamp}\n"
        f"# Integrity   : {tag}\n"
        f"# Pass this file to --key or place it next to the capture for auto-load.\n"
    )

    # Atomic write: same-directory tempfile then os.replace.
    directory = os.path.dirname(os.path.abspath(path)) or "."
    fd, tmp_path = tempfile.mkstemp(prefix=".anonymizer_key_", dir=directory, text=True)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(contents)
        # Restrict permissions before swapping into place (POSIX only;
        # on Windows os.chmod is mostly a no-op but harmless).
        if sys.platform != "win32":
            os.chmod(tmp_path, stat.S_IRUSR | stat.S_IWUSR)  # 0600
        os.replace(tmp_path, path)
    except Exception:
        # Clean up the temp file on failure; don't mask the original exception.
        if os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except OSError:
                pass
        raise

    logger.info("Wrote encryption key to %s (mode 0600)", path)


def load_key_from_file(path: str) -> bytes:
    """Load and validate a key previously written by :func:`save_key`.

    Raises :class:`InvalidKeyError` for missing files, malformed base64,
    wrong key length, or a failed integrity check.
    """
    if not os.path.exists(path):
        raise InvalidKeyError(f"Key file not found: {path}")

    expected_tag: Optional[str] = None
    key_b64: Optional[str] = None

    try:
        with open(path, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                if key_b64 is None and not line.startswith("#"):
                    key_b64 = line
                elif line.startswith("# Integrity"):
                    # Tolerate a few different spacings.
                    expected_tag = line.split(":", 1)[-1].strip()
    except OSError as exc:
        raise InvalidKeyError(f"Cannot read key file {path!r}: {exc}") from exc

    if not key_b64:
        raise InvalidKeyError(f"No key found in {path!r}")

    return decode_key_b64(key_b64, expected_tag=expected_tag, source=path)


def decode_key_b64(
    key_b64: str,
    *,
    expected_tag: Optional[str] = None,
    source: str = "<argument>",
) -> bytes:
    """Decode a base64-encoded key string and run integrity checks."""
    try:
        key = base64.b64decode(key_b64, validate=True)
    except (ValueError, base64.binascii.Error) as exc:  # type: ignore[attr-defined]
        raise InvalidKeyError(f"Invalid base64 key from {source!r}: {exc}") from exc

    if len(key) != KEY_LENGTH:
        raise InvalidKeyError(
            f"Key from {source!r} has wrong length ({len(key)}); expected {KEY_LENGTH}"
        )

    if expected_tag is not None:
        actual = _integrity_tag(key)
        # Constant-time comparison even though the tag isn't secret;
        # discipline matters more than the marginal performance.
        if not hmac.compare_digest(expected_tag, actual):
            raise InvalidKeyError(
                f"Integrity tag mismatch for {source!r}; file may have been edited"
            )

    return key
